use vstd::prelude::*;
verus! {

    /// In‐place reverse of the inclusive prefix [0..=num] of a non‐empty vector.
    fn flip(a: &mut Vec<i32>, num: usize)
        requires
            // The array must be non‐empty
            a.len() > 0,
            // num must be a valid index into a
            num < a.len();
        ensures
            // length is unchanged
            a.len() == old(a.len()),
        ensures
            // every position k in [0..=num] is reversed
            forall |k: usize|
                k <= num
                ==> a[k] == old(a[num - k]),
        ensures
            // elements beyond num are untouched
            forall |k: usize|
                num < k && k < a.len()
                ==> a[k] == old(a[k]);
    {
        let mut i: usize = 0;
        let mut j: usize = num;

        // We maintain three facts at each iteration:
        //  1)  All indices < i have been swapped into their final reversed positions.
        //  2)  All indices > j (but ≤ num) have likewise been swapped into their final positions.
        //  3)  All indices > num are never touched.
        // The remaining slice [i..=j] is still “to be processed.”
        // We also need i ≤ j+1 so that (j+1)-i is a non‐negative natural for `decreases`.
        while i < j {
            invariant i <= j + 1;
            invariant j <= num;
            invariant forall |k: usize| k < i ==> a[k] == old(a)[num - k];
            invariant forall |k: usize| j < k && k <= num ==> a[k] == old(a)[num - k];
            invariant forall |k: usize| num < k && k < a.len() ==> a[k] == old(a)[k];
            decreases (j + 1) - i;

            // swap the two “mirrored” elements
            a.swap(i, j);

            // move the pointers inward
            i += 1;
            j -= 1;
        }
        // when the loop exits, i ≥ j; if i == j there is a middle element,
        // but it is already in the correct (self‐mirrored) position.
    }

}